import {START,LEARN_END,REV_START,END,EXAM,TOPICS,STAGES,WEIGHTS,createState,replan,rollover,toggleTask,moveTask,validateState,localToday,dateObj,iso,addDays,diffDays,range,weightName,topicOf,prevTask} from './planner.js';
const KEY='little-by-little.v1',UNDO=KEY+'.undo';
let state,storageError='',today=localToday(),page=['today','calendar','topics','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'today',selected=today<START?START:today>END?END:today,month=selected.slice(0,7),activeId=null,toastTimer;
const main=document.querySelector('#main'),dialog=document.querySelector('#session-dialog');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(d,opts={month:'short',day:'numeric'})=>dateObj(d).toLocaleDateString('en-AU',opts);
const longDate=d=>fmt(d,{weekday:'long',month:'long',day:'numeric'});
const getTask=id=>state.tasks.find(t=>t.id===id);
try {const saved=localStorage.getItem(KEY);state=saved?validateState(JSON.parse(saved)):createState(today);rollover(state,today);} catch(e){state=createState(today);storageError='Saved progress could not be loaded. Your existing data has not been overwritten; export or restore a backup from Your rhythm.';}
function save(){try{if(storageError)throw Error();localStorage.setItem(KEY,JSON.stringify(state));}catch{storageError=storageError||'Device storage is unavailable. Keep this tab open and export a backup to keep your progress.';}updateStorageBadge();}
function updateStorageBadge(){document.querySelector('.local-badge').innerHTML=`<i></i> ${storageError?'Backup needed':'Saved on this device'}`;}
function snapshot(){try{localStorage.setItem(UNDO,JSON.stringify(state));}catch{}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function mutate(fn,message){const before=structuredClone(state);try{fn();try{localStorage.setItem(UNDO,JSON.stringify(before));}catch{}save();render();if(message)toast(message);return true;}catch(e){state=before;toast(e.message);return false;}}
function navigate(next){page=next;history.replaceState(null,'','#'+next);render();window.scrollTo({top:0,behavior:'instant'});}
function header(title,subtitle,eyebrow='YOUR STUDY PLAN',pill=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${pill?`<span class="phase-pill">● &nbsp; ${pill}</span>`:''}</div>`;}
function warnings(){return [...(storageError?[storageError]:[]),...(state.notices||[])].map(n=>`<div class="notice">${esc(n)}</div>`).join('');}
function sessionCard(t){const p=topicOf(t),prev=prevTask(state,t);const blocked=!t.doneAt&&t.stage>0&&(!prev?.doneAt||today<REV_START||diffDays(today,prev.doneAt)<(t.stage===1?1:3));return `<article class="task-card ${t.doneAt?'done':''}" ${!t.doneAt?'draggable="true"':''} data-task="${t.id}"><button class="check" data-toggle="${t.id}" aria-pressed="${!!t.doneAt}" aria-label="${t.doneAt?'Undo':'Complete'} ${esc(p.title)} ${STAGES[t.stage]}" ${blocked?'aria-disabled="true"':''}>${t.doneAt?'✓':''}</button><div class="task-copy"><div class="task-meta"><span class="subject ${p.subject.toLowerCase()}">${p.subject.toUpperCase()}</span><span>VIDEO ${String(p.number).padStart(2,'0')} · ${STAGES[t.stage].toUpperCase()}</span>${t.pinned?'<span title="Manually scheduled">⌁ MOVED</span>':''}</div><h3>${esc(p.title)}</h3>${t.rolledFrom&&!t.doneAt?`<div class="carry-label">Carried from ${fmt(t.rolledFrom)}</div>`:''}${!t.date&&!t.doneAt?'<div class="carry-label">Needs a study day</div>':''}</div><button class="more" data-session="${t.id}" aria-label="Schedule ${esc(p.title)} ${STAGES[t.stage]}">↗</button></article>`;}
function dayTasks(d){return state.tasks.filter(t=>t.date===d).sort((a,b)=>!!a.doneAt-!!b.doneAt||a.stage-b.stage);}
function todayPage(){const tasks=dayTasks(today),backlog=state.tasks.filter(t=>!t.date&&!t.doneAt),done=state.tasks.filter(t=>t.doneAt).length,remaining=tasks.filter(t=>!t.doneAt).length;const phase=today<REV_START?'First pass':today<EXAM?'Spaced revision':'Exam day & beyond';const days=diffDays(EXAM,today);return header(days===0?'You’ve put in<br>the work.':'A little progress,<br>a lot closer.',remaining?`${remaining} session${remaining===1?'':'s'} today. One topic at a time.`:tasks.length?'Today’s sessions are complete. Take a well-earned breath.':'A little room to breathe. Your next steps are on the calendar.',longDate(today).toUpperCase(),phase)+warnings()+`<div class="dashboard"><section><div class="progress-card"><div class="small-label">YOUR PATH TO EXAM DAY</div><div class="milestones">${['Learn','Recall','Revisit'].map((label,i)=>`<div><span class="milestone ${state.tasks.filter(t=>t.stage===i&&t.doneAt).length===21||i===(today<REV_START?0:1)?'active':''}">${state.tasks.filter(t=>t.stage===i&&t.doneAt).length===21?'✓':i+1}</span><b>${label}</b><small>${['By Sep 26','From Sep 27','By Oct 14'][i]}</small></div>`).join('')}</div><div class="progress-track" role="progressbar" aria-label="Total study progress" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="63"><span style="width:${done/63*100}%"></span></div><div class="progress-caption"><span>${done} of 63 sessions complete</span><span>${days>0?`${days} days to go`:days===0?'Exam day':'Exam date passed'}</span></div></div><div class="section-title"><h2>Today’s focus <span class="count">${tasks.length}</span></h2><span class="subtle">${{off:'Rest day',light:'Light day',normal:'Steady day',heavy:'Heavy day'}[weightName(state,today)]}</span></div><div class="task-list">${tasks.length?tasks.map(sessionCard).join(''):`<div class="empty"><strong>${today>END?'Your study journey':'Space to recharge.'}</strong>${today>END?'Your completed sessions are in All topics.':'Nothing scheduled today. Explore your calendar to see what’s next.'}<br><button class="text-button" data-page="calendar">Open your calendar →</button></div>`}</div>${backlog.length?`<div class="section-title"><h2>Needs a place <span class="count">${backlog.length}</span></h2></div><p class="subtle">These sessions could not fit. Adjust your rhythm or open a session to choose a day.</p><div class="task-list">${backlog.map(sessionCard).join('')}</div>`:''}<p class="subtle spacer">${today<REV_START?'Watch, take a few notes, and tick it off. We’ll bring each topic back twice.':'Close your notes first. Recall the key points, then check the gaps.'}</p></section><aside class="right-column"><div class="note-card"><span class="star" aria-hidden="true">✳</span><div class="small-label">A PLAN THAT BENDS</div><h2>Life happens.<br>Your plan keeps up.</h2><p>Miss a day? Unfinished sessions roll forward and spread across the days ahead.</p><button class="text-button" data-page="settings">Find your rhythm ↗</button></div><div class="week-card"><div class="section-title"><h2>Your next 7 days</h2><button class="text-button" data-page="calendar">View all ↗</button></div><div class="week-bars">${range(today,addDays(today,6)).map(d=>{const n=dayTasks(d).length;return `<button class="bar-day ${d===today?'is-today':''}" data-day="${d}" aria-label="${longDate(d)}, ${n} sessions"><small>${n}</small><span class="bar" style="--height:${Math.min(n*14+5,76)}px"></span><span>${fmt(d,{weekday:'narrow'})}</span></button>`;}).join('')}</div><div class="week-key"><i></i> Sessions planned · weighted to your rhythm</div><button class="text-button install-link" data-install>Add to your iPhone ↗</button></div></aside></div>`;}
function weightOptions(current,inherit=false){return `${inherit?'<option value="default">Weekly default</option>':''}${Object.keys(WEIGHTS).map(w=>`<option value="${w}" ${w===current?'selected':''}>${{off:'Off · no sessions',light:'Light · ½ load',normal:'Normal · 1× load',heavy:'Heavy · 2× load'}[w]}</option>`).join('')}`;}
function calendarPage(){const first=month+'-01',offset=(dateObj(first).getDay()+6)%7,start=addDays(first,-offset);return header('Make room<br>for what matters.','Tap a day to see its sessions. Move or swap a topic with the ↗ button.','YOUR CALENDAR')+warnings()+`<div class="calendar-layout"><section class="calendar-card"><div class="calendar-toolbar"><h2>${fmt(first,{month:'long',year:'numeric'})}</h2><div class="actions"><button class="icon-button" data-month="-1" aria-label="Previous month" ${month<='2026-09'?'disabled':''}>‹</button><button class="text-button" data-day="${today<START?START:today>END?END:today}">Today</button><button class="icon-button" data-month="1" aria-label="Next month" ${month>='2026-10'?'disabled':''}>›</button></div></div><div class="weekdays">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d=>`<span>${d}</span>`).join('')}</div><div class="month-grid">${range(start,addDays(start,Math.ceil((offset+new Date(dateObj(first).getFullYear(),dateObj(first).getMonth()+1,0).getDate())/7)*7-1)).map(d=>{const tasks=dayTasks(d),active=d>=START&&d<=EXAM;return `<button class="day ${d.slice(0,7)!==month?'outside':''} ${tasks.length?'has-tasks':''} ${selected===d?'selected':''} ${d===today?'is-today':''} ${d===EXAM?'exam':''}" data-day="${d}" ${!active?'disabled':''} aria-pressed="${selected===d}" aria-label="${longDate(d)}, ${tasks.length} sessions${d===EXAM?', exam day':''}"><span class="day-number">${dateObj(d).getDate()}</span>${active&&d!==EXAM?`<span class="day-weight">${{heavy:'＋',light:'−',off:'·',normal:''}[weightName(state,d)]}</span>`:''}<span class="day-dots">${tasks.slice(0,6).map(t=>`<i class="${t.stage?'rev':''} ${t.doneAt?'completed':''}"></i>`).join('')}</span><span class="day-load">${d===EXAM?'EXAM':tasks.length?`${tasks.filter(t=>t.doneAt).length}/${tasks.length} done`:active?'Free':''}</span></button>`;}).join('')}</div><div class="calendar-legend"><span><i class="dot"></i> First pass</span><span><i class="dot revision"></i> Revision</span><span>＋ Heavy &nbsp; − Light</span></div><p class="subtle spacer">First pass: Sep 18–26 · Revision: Sep 27–Oct 14.<br>On a computer, you can also drag a session onto a day.</p></section><section class="day-detail"><div class="eyebrow">${fmt(selected,{weekday:'long'}).toUpperCase()}</div><h2 class="selected-day-heading">${fmt(selected,{month:'long',day:'numeric'})}</h2>${selected<EXAM?`<label class="select-label">This day’s workload<select id="day-weight" aria-label="Selected day workload">${weightOptions(state.overrides[selected]||'default',true)}</select></label>`:'<p class="subtle">Exam day. Take a breath. You’ve got this.</p>'}<div class="task-list">${dayTasks(selected).length?dayTasks(selected).map(sessionCard).join(''):'<div class="empty"><strong>A little breathing room.</strong>No sessions scheduled.</div>'}</div>${selected<EXAM?'<p class="subtle spacer">Changing the workload redistributes unfinished, unpinned sessions. Completed sessions stay put.</p>':''}</section></div>`;}
function topicsPage(){return header('Every topic.<br>A little more familiar.','21 videos. Two return visits each. A clear path to October 15.','THE BIG PICTURE')+warnings()+`<div class="stat-row">${STAGES.map((s,i)=>`<div class="stat"><strong>${state.tasks.filter(t=>t.stage===i&&t.doneAt).length}<span style="font-family:inherit;font-size:20px"> / 21</span></strong><span>${s==='First pass'?'Videos watched':s+' complete'}</span></div>`).join('')}</div>${['Eye','ENT'].map(subject=>`<section class="topic-group"><h2>${subject} <span class="count">${TOPICS.filter(p=>p.subject===subject).length}</span></h2>${TOPICS.filter(p=>p.subject===subject).map(p=>`<div class="topic-row"><span class="topic-number">${String(p.number).padStart(2,'0')}</span><h3>${esc(p.title)}</h3><div class="topic-stages">${[0,1,2].map(i=>{const t=getTask(`${p.id}:${i}`);return `<button class="stage-chip ${t.doneAt?'completed':''}" data-session="${t.id}" aria-label="${esc(p.title)} ${STAGES[i]} ${t.doneAt?'complete':t.date?fmt(t.date):'unscheduled'}">${t.doneAt?'✓ ':''}${['Watch','R1','R2'][i]} · ${t.date?fmt(t.date):'Unplaced'}</button>`;}).join('')}</div></div>`).join('')}</section>`).join('')}`;}
function settingsPage(){return header('Study at<br>your own rhythm.','A lighter Monday. A bigger Saturday. Make the plan fit your life.','YOUR RHYTHM')+warnings()+`<div class="settings-grid"><section class="panel"><h2>A week that works for you</h2><p>Light days carry half the normal load; heavy days carry twice as much. Off days get no automatic sessions. Each session counts equally because video lengths aren’t supplied.</p><form id="rhythm-form">${[1,2,3,4,5,6,0].map(d=>`<div class="rhythm-row"><label for="weekday-${d}">${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][d]}</label><select name="weekday-${d}" id="weekday-${d}">${weightOptions(state.weekly[d])}</select></div>`).join('')}<label class="field">First study day<input name="start" type="date" value="${state.start}" min="2026-09-18" max="2026-09-26" required></label><button class="button" type="submit">Save rhythm & rebalance</button><p>Manual moves stay fixed unless they conflict with the review order. Change individual days in Calendar.</p></form></section><div class="settings-stack"><section class="panel"><h2>How your plan works</h2><ol class="rule-list"><li>All 21 first viewings are planned by the end of September 26.</li><li>Revision begins September 27. First recall follows watching; the second review aims for about a week later, with a minimum 3-day gap.</li><li>Both reviews are planned by October 14. Missed work spreads over the remaining available days when you reopen the app.</li><li>If dates or off days make that impossible, sessions stay visible under “Needs a place”.</li></ol><p>Spaced repetition inspired. For revision, try recalling the topic before checking your notes.</p></section><section class="panel"><h2>Your plan, on this device</h2><p>No account. No cloud sync. Export a backup to keep progress safe or move it to another device.</p><div class="actions"><button class="button secondary" data-export>Export backup</button><button class="button secondary" data-import>Restore backup</button><input id="import-file" type="file" accept="application/json,.json" hidden></div><div class="actions spacer"><button class="text-button" data-undo>Undo last change</button><button class="text-button" data-rebalance>Release moves & rebalance</button></div><button class="text-button install-link" data-install>Add to your iPhone ↗</button></section></div></div>`;}
function render(){document.querySelector('#header-date').textContent=longDate(today);document.querySelectorAll('nav [data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});main.innerHTML=({today:todayPage,calendar:calendarPage,topics:topicsPage,settings:settingsPage})[page]();updateStorageBadge();}
function openSession(id){activeId=id;const t=getTask(id),p=topicOf(t);dialog.innerHTML=`<button class="dialog-close" data-close aria-label="Close session">×</button><span class="subject ${p.subject.toLowerCase()}">${p.subject.toUpperCase()} · ${STAGES[t.stage].toUpperCase()}</span><h2>${esc(p.title)}</h2><p>${t.doneAt?`Completed ${fmt(t.doneAt)}.`:`Scheduled ${t.date?longDate(t.date):'when a study day becomes available'}.`} ${t.stage?'Try recalling the key points before opening your notes.':'Watch the lecture, then tick it off.'}</p><button class="button" data-modal-toggle="${id}">${t.doneAt?'Undo completion':'Mark complete today'}</button>${!t.doneAt?`<form id="move-form"><label class="field">Move to a day<input type="date" id="move-date" name="date" min="${today>state.start?today:state.start}" max="${t.stage===0&&today<=LEARN_END?LEARN_END:END}" value="${t.date||today}" required></label><label class="field">Move or swap<select id="swap-with" name="swap" aria-label="Move or swap"><option value="">Move this session only</option></select></label><p class="badge">Moving shifts this session; swapping exchanges two dates. Later reviews adjust if needed. Manual choices stay pinned when rebalancing, including on off days.</p><div class="dialog-error" id="move-error" role="alert"></div><button class="button secondary" type="submit">Save schedule</button></form>`:''}<p class="badge spacer">${[0,1,2].map(i=>{const x=getTask(`${p.id}:${i}`);return `${STAGES[i]}: ${x.date?fmt(x.date):'unplaced'}${x.doneAt?' ✓':''}`;}).join(' &nbsp; · &nbsp; ')}</p>`;if(!t.doneAt)fillSwaps();if(!dialog.open)dialog.showModal();}
function fillSwaps(){const d=document.querySelector('#move-date').value,options=state.tasks.filter(t=>!t.doneAt&&t.id!==activeId&&t.date===d);document.querySelector('#swap-with').innerHTML='<option value="">Move this session only</option>'+options.map(t=>`<option value="${t.id}">Swap with ${esc(topicOf(t).title)} · ${STAGES[t.stage]}</option>`).join('');}
function installHelp(){const el=document.querySelector('#help-dialog');el.innerHTML=`<button class="dialog-close" data-close aria-label="Close help">×</button><div class="eyebrow">TAKE IT WITH YOU</div><h2>A little space<br>on your home screen.</h2><ol class="rule-list"><li>Open the app’s secure (HTTPS) address in Safari on your iPhone.</li><li>Tap Share, then <strong>Add to Home Screen</strong>. If shown, turn on <strong>Open as Web App</strong>.</li><li>Open it once while connected. After the offline status below says ready, the app and your progress work offline.</li></ol><div class="notice">This preview lives on this Mac. “localhost” on an iPhone points to the iPhone itself. For installation, serve this app over HTTPS on your own server or use a trusted HTTPS tunnel to this Mac.</div><p id="offline-status">${offlineStatus}</p><p>Progress is stored in this browser or installed app. Export a backup before switching devices or clearing website data.</p>`;el.showModal();}
let offlineStatus='Checking offline support…';
function showOfflineStatus(ready){const el=document.querySelector('#offline-badge');if(el)el.textContent=ready?'LOCAL · OFFLINE READY':'LOCAL · BACKUP AVAILABLE';const status=document.querySelector('#offline-status');if(status)status.textContent=offlineStatus;}
document.addEventListener('click',e=>{const b=e.target.closest('button, a.brand');if(!b)return;if(b.matches('a.brand')){e.preventDefault();navigate('today');}else if(b.dataset.page)navigate(b.dataset.page);else if(b.dataset.toggle)mutate(()=>toggleTask(state,b.dataset.toggle,today),getTask(b.dataset.toggle).doneAt?'Completion undone.':'One step closer. Session complete.');else if(b.dataset.session)openSession(b.dataset.session);else if(b.dataset.modalToggle){if(mutate(()=>toggleTask(state,b.dataset.modalToggle,today),'Progress updated.'))dialog.close();}else if(b.hasAttribute('data-close'))b.closest('dialog').close();else if(b.dataset.day){selected=b.dataset.day;month=selected.slice(0,7);navigate('calendar');if(matchMedia('(max-width:600px)').matches)requestAnimationFrame(()=>document.querySelector('.day-detail').scrollIntoView({block:'start',behavior:'smooth'}));}else if(b.dataset.month){const d=dateObj(month+'-01');d.setMonth(d.getMonth()+Number(b.dataset.month));month=iso(d).slice(0,7);render();}else if(b.hasAttribute('data-install'))installHelp();else if(b.hasAttribute('data-export')){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`little-by-little-${today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported.');}else if(b.hasAttribute('data-import'))document.querySelector('#import-file').click();else if(b.hasAttribute('data-undo')){try{const raw=localStorage.getItem(UNDO);if(!raw)throw Error('No recent change to undo.');const previous=validateState(JSON.parse(raw));const current=JSON.stringify(state);state=previous;rollover(state,today);localStorage.setItem(UNDO,current);save();render();toast('Last change undone.');}catch(e){toast(e.message);}}else if(b.hasAttribute('data-rebalance'))mutate(()=>replan(state,today,{releasePins:true}),'Manual moves released. Unfinished sessions rebalanced.');});
document.addEventListener('change',async e=>{if(e.target.id==='day-weight')mutate(()=>{if(e.target.value==='default')delete state.overrides[selected];else state.overrides[selected]=e.target.value;replan(state,today);},'Day updated. Your plan has been rebalanced.');else if(e.target.id==='move-date')fillSwaps();else if(e.target.id==='import-file'){const file=e.target.files?.[0];if(!file)return;try{if(file.size>1000000)throw Error('Choose a Little by little JSON backup under 1 MB.');const restored=validateState(JSON.parse(await file.text()));snapshot();state=restored;storageError='';replan(state,today);save();render();toast('Backup restored. Use Undo last change to reverse.');}catch(err){toast('Could not restore: '+err.message);}}});
document.addEventListener('submit',e=>{if(e.target.id==='rhythm-form'){e.preventDefault();const f=new FormData(e.target);mutate(()=>{state.weekly=Array.from({length:7},(_,i)=>f.get('weekday-'+i));state.start=f.get('start');replan(state,today);},'Your rhythm is saved. The plan is balanced.');}else if(e.target.id==='move-form'){e.preventDefault();const f=new FormData(e.target),before=structuredClone(state);try{moveTask(state,activeId,f.get('date'),today,f.get('swap')||null);try{localStorage.setItem(UNDO,JSON.stringify(before));}catch{}save();render();dialog.close();toast(f.get('swap')?'Sessions swapped.':'Session moved. Later reviews adjusted if needed.');}catch(err){state=before;document.querySelector('#move-error').textContent=err.message;}}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-task]');if(card){e.dataTransfer.setData('text/plain',card.dataset.task);e.dataTransfer.effectAllowed='move';}});
document.addEventListener('dragover',e=>{if(e.target.closest('.day:not(:disabled)'))e.preventDefault();});
document.addEventListener('drop',e=>{const d=e.target.closest('.day:not(:disabled)');if(d){e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(getTask(id))mutate(()=>moveTask(state,id,d.dataset.day,today),'Session moved.');}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(['today','calendar','topics','settings'].includes(p)){page=p;render();}});
function checkDay(){const next=localToday();if(next!==today){today=next;rollover(state,today);save();render();}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkDay();});setInterval(checkDay,60000);
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=validateState(JSON.parse(e.newValue));rollover(state,today);render();toast('Progress updated from another tab.');}catch{}}});
save();render();
if('serviceWorker' in navigator&&window.isSecureContext){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineStatus='Offline ready. The app can open without a connection on this device.';showOfflineStatus(true);}).catch(()=>{offlineStatus='Offline setup did not finish. Reconnect and reload to try again.';showOfflineStatus(false);});}else {offlineStatus='Offline installation needs HTTPS (or localhost on this Mac).';showOfflineStatus(false);}
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'read_study_plan',description:'Read the local Eye and ENT study schedule and completion status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({today,tasks:state.tasks.map(t=>({id:t.id,title:topicOf(t).title,stage:STAGES[t.stage],date:t.date,completed:!!t.doneAt})),notices:state.notices})});
 register({name:'move_study_session',description:'Move an unfinished session to a date, adjusting dependent reviews. Optionally swap with a session on that date.',inputSchema:{type:'object',properties:{id:{type:'string'},date:{type:'string'},swapId:{type:'string'}},required:['id','date'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.id!=='string'||typeof input.date!=='string'||(input.swapId!==undefined&&typeof input.swapId!=='string'))throw Error('Provide a session id and YYYY-MM-DD date.');const before=structuredClone(state);moveTask(state,input.id,input.date,today,input.swapId||null);try{localStorage.setItem(UNDO,JSON.stringify(before));}catch{}save();render();return {id:input.id,date:getTask(input.id).date};}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
